1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.time.LocalDate;
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "toDisplayName")
24	    @Mapping(target = "salutation", source = "owner", qualifiedByName = "toSalutation")
25	    @Mapping(target = "telephoneDisplay", source = "owner", qualifiedByName = "toTelephoneDisplay")
26	    @Mapping(target = "initials", source = "owner", qualifiedByName = "toInitials")
27	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "toMembershipNumber")
28	    @Mapping(target = "fiscalYear", source = "owner", qualifiedByName = "toFiscalYear")
29	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "toCheckDigit")
30	    @Mapping(target = "membershipPoints", source = "owner", qualifiedByName = "toMembershipPoints")
31	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "toMembershipLevel")
32	    @Mapping(target = "locality", source = "owner", qualifiedByName = "toLocality")
33	    @Mapping(target = "timezone", source = "owner", qualifiedByName = "toTimezone")
34	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "toContactPreference")
35	    @Mapping(target = "identityKey", source = "owner", qualifiedByName = "toIdentityKey")
36	    @Mapping(target = "ageBand", source = "owner", qualifiedByName = "toAgeBand")
37	    @Mapping(target = "selfLink", source = "owner", qualifiedByName = "toSelfLink")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * Derives the owner's {@code selfLink}: its canonical relative URL, {@code '/api/owners/'}
42	     * followed by the owner's id. Returns {@code null} when the owner has no id yet.
43	     */
44	    @Named("toSelfLink")
45	    default String toSelfLink(Owner owner) {
46	        if (owner == null || owner.getId() == null) {
47	            return null;
48	        }
49	        return "/api/owners/" + owner.getId();
50	    }
51	
52	    /**
53	     * Derives the owner's {@code ageBand} from its {@code birthDate}, computed against the
54	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18 on the registration date,
55	     * {@code 'ADULT'} from 18 up to and including 64, and {@code 'SENIOR'} at 65 or over. Returns
56	     * {@code null} when either the birth date or the registration date is absent.
57	     */
58	    @Named("toAgeBand")
59	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
60	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
61	            return null;
62	        }
63	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
64	        if (age < 18) {
65	            return OwnerDto.AgeBandEnum.MINOR;
66	        }
67	        if (age < 65) {
68	            return OwnerDto.AgeBandEnum.ADULT;
69	        }
70	        return OwnerDto.AgeBandEnum.SENIOR;
71	    }
72	
73	    /**
74	     * Derives the owner's duplicate-detection {@code identityKey}: the single key that consolidates
75	     * the former separate telephone, email and household checks. It is the lower-case, 64-character
76	     * SHA-256 hex digest of {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)},
77	     * where {@code lowerEmail} is the email trimmed and lower-cased (or the empty string when absent)
78	     * and {@code soundex(lastName)} is the American Soundex code of the owner's last name. Because the
79	     * telephone is part of the key, two owners with the same last name (same soundex) and postcode but
80	     * different telephones have different identity keys; only an exact full-key match is a duplicate.
81	     */
82	    @Named("toIdentityKey")
83	    default String toIdentityKey(Owner owner) {
84	        if (owner == null) {
85	            return null;
86	        }
87	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
88	        String email = owner.getEmail() == null ? "" : owner.getEmail().trim().toLowerCase(java.util.Locale.ROOT);
89	        String soundex = OwnerIdentity.soundex(owner.getLastName());
90	        return OwnerIdentity.sha256Hex(telephone + "|" + email + "|" + soundex);
91	    }
92	
93	    /**
94	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when the owner has a non-blank
95	     * email, otherwise {@code 'PHONE'}.
96	     */
97	    @Named("toContactPreference")
98	    default String toContactPreference(Owner owner) {
99	        if (owner == null) {
100	            return null;
101	        }
102	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
103	        return hasEmail ? "EMAIL" : "PHONE";
104	    }
105	
106	    /**
107	     * Fixed city-to-region table used as the fallback for deriving an owner's locality.
108	     */
109	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
110	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
111	
112	    /**
113	     * Fixed region-to-timezone table mapping each canonical region to its IANA timezone name
114	     * ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}).
115	     */
116	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
117	        "NSW", "Australia/Sydney",
118	        "VIC", "Australia/Melbourne",
119	        "QLD", "Australia/Brisbane");
120	
121	    /**
122	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
123	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Used to derive an
124	     * owner's locality from its postcode in preference to its city.
125	     */
126	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
127	        "NSW", new int[] {2000, 2099},
128	        "VIC", new int[] {3000, 3099},
129	        "QLD", new int[] {4000, 4099});
130	
131	    /**
132	     * Derives the owner's canonical region, the {@code REGION} component of its {@code customerCode}.
133	     * The postcode takes precedence: when the owner has a well-formed 4-digit postcode that falls
134	     * within a known region's range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD
135	     * 4000-4099}), that region is returned. Otherwise the region is looked up from the fixed
136	     * city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}),
137	     * yielding {@code 'UNKNOWN'} when the city is not in the table. Preferring the postcode returns
138	     * the same region for known cities but disambiguates cities that share a name.
139	     */
140	    default String toRegion(Owner owner) {
141	        if (owner == null) {
142	            return null;
143	        }
144	        String regionByPostcode = regionForPostcode(owner.getPostcode());
145	        if (regionByPostcode != null) {
146	            return regionByPostcode;
147	        }
148	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
149	    }
150	
151	    /**
152	     * Derives the owner's locality as the {@code REGION} component of its region-and-hash
153	     * {@code customerCode} (the prefix before the first {@code '-'}). The locality therefore shares
154	     * the customer code's identity rather than being computed independently. When the customer code
155	     * is absent the region is derived directly from the owner's postcode and city via
156	     * {@link #toRegion(Owner)}.
157	     */
158	    @Named("toLocality")
159	    default String toLocality(Owner owner) {
160	        if (owner == null) {
161	            return null;
162	        }
163	        String customerCode = owner.getCustomerCode();
164	        if (customerCode != null) {
165	            int dash = customerCode.indexOf('-');
166	            if (dash >= 0) {
167	                return customerCode.substring(0, dash);
168	            }
169	        }
170	        return toRegion(owner);
171	    }
172	
173	    /**
174	     * Derives the owner's {@code timezone} as the IANA timezone name mapped from its locality/region
175	     * via the fixed region-to-timezone table ({@code NSW->Australia/Sydney},
176	     * {@code VIC->Australia/Melbourne}, {@code QLD->Australia/Brisbane}). Returns {@code null} when the
177	     * owner's region is not one of the tabled regions.
178	     */
179	    @Named("toTimezone")
180	    default String toTimezone(Owner owner) {
181	        if (owner == null) {
182	            return null;
183	        }
184	        return REGION_TIMEZONE.get(toLocality(owner));
185	    }
186	
187	    /**
188	     * Returns the region whose inclusive postcode range contains the given 4-digit postcode, or
189	     * {@code null} when the postcode is absent, malformed, or in no known range.
190	     */
191	    private static String regionForPostcode(String postcode) {
192	        if (postcode == null || !postcode.matches("\\d{4}")) {
193	            return null;
194	        }
195	        int value = Integer.parseInt(postcode);
196	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
197	            int[] range = entry.getValue();
198	            if (value >= range[0] && value <= range[1]) {
199	                return entry.getKey();
200	            }
201	        }
202	        return null;
203	    }
204	
205	    /**
206	     * Formats the owner's stored names as {@code 'LastName, FirstName'}.
207	     */
208	    @Named("toDisplayName")
209	    default String toDisplayName(Owner owner) {
210	        if (owner == null) {
211	            return null;
212	        }
213	        return owner.getLastName() + ", " + owner.getFirstName();
214	    }
215	
216	    /**
217	     * Composes the owner's {@code salutation}: the owner's {@code title} and {@code lastName} joined
218	     * by a single space when a title is present, or just the {@code lastName} when no title is
219	     * supplied (absent or blank).
220	     */
221	    @Named("toSalutation")
222	    default String toSalutation(Owner owner) {
223	        if (owner == null) {
224	            return null;
225	        }
226	        String title = owner.getTitle();
227	        if (title == null || title.isBlank()) {
228	            return owner.getLastName();
229	        }
230	        return title + " " + owner.getLastName();
231	    }
232	
233	    /**
234	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
235	     * the national digits grouped in threes, e.g. {@code "+61412345678"} becomes
236	     * {@code "+61 412 345 678"}. The country code is a single {@code '1'} for NANP ({@code +1}) numbers
237	     * and two digits otherwise (covering the {@code +61} numbers the app stores). Returns the value
238	     * unchanged when it is absent or not a well-formed E.164 number, leaving raw {@code telephone}
239	     * untouched.
240	     */
241	    @Named("toTelephoneDisplay")
242	    default String toTelephoneDisplay(Owner owner) {
243	        if (owner == null) {
244	            return null;
245	        }
246	        String telephone = owner.getTelephone();
247	        if (telephone == null || !telephone.matches("\\+[0-9]{8,15}")) {
248	            return telephone;
249	        }
250	        String digits = telephone.substring(1);
251	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
252	        String countryCode = digits.substring(0, countryCodeLength);
253	        String national = digits.substring(countryCodeLength);
254	        StringBuilder sb = new StringBuilder("+").append(countryCode);
255	        for (int i = 0; i < national.length(); i++) {
256	            if (i % 3 == 0) {
257	                sb.append(' ');
258	            }
259	            sb.append(national.charAt(i));
260	        }
261	        return sb.toString();
262	    }
263	
264	    /**
265	     * Returns the owner's initials as the upper-cased first letters of firstName and lastName,
266	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
267	     */
268	    @Named("toInitials")
269	    default String toInitials(Owner owner) {
270	        if (owner == null) {
271	            return null;
272	        }
273	        return initial(owner.getFirstName()) + initial(owner.getLastName());
274	    }
275	
276	    /**
277	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}, where {@code YY} is
278	     * the last two digits of the fiscal year of the {@code registrationDate}, e.g.
279	     * {@code 'NSW-1A2B3C4D-M26'}. The fiscal year starts on 1 July and is identified by the calendar
280	     * year in which it ends. Returns {@code null} when either the customer code or the registration
