305	    }
306	
307	    /**
308	     * Returns the fiscal year of the given date as the calendar year in which the fiscal year ends.
309	     * The fiscal year starts on 1 July, so a date in July or later belongs to the fiscal year ending
310	     * in the next calendar year ({@code year + 1}); an earlier date belongs to the fiscal year ending
311	     * in its own calendar year.
312	     *
313	     * @param date the date whose fiscal year is computed, never {@code null}
314	     * @return the calendar year in which the date's fiscal year ends
315	     */
316	    static int fiscalYear(LocalDate date) {
317	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
318	    }
319	
320	    /**
321	     * Returns the owner's membership points, assigned on creation: starts at {@code 0}, plus {@code 2}
322	     * when a non-blank email is present, plus {@code 1} when the owner has no namesakes
323	     * ({@code namesakeCount} is 0), plus {@code 2} for a household of {@code 3} or more members, plus
324	     * {@code 3} for a tenure of one or more elapsed fiscal years since the {@code registrationDate}.
325	     * This qualified mapping cannot observe the owner's household size (which requires counting other
326	     * owners), so it computes the points as if the owner were the only member of its household; the
327	     * controller recomputes the points with the real household size via
328	     * {@link #membershipPointsFor(Owner, int)} before returning the owner.
329	     */
330	    @Named("toMembershipPoints")
331	    default Integer toMembershipPoints(Owner owner) {
