411	        if (owner == null || owner.getCustomerCode() == null) {
412	            return null;
413	        }
414	        int sum = 0;
415	        boolean dbl = true;
416	        String code = owner.getCustomerCode();
417	        for (int i = code.length() - 1; i >= 0; i--) {
418	            char c = code.charAt(i);
419	            if (c < '0' || c > '9') {
420	                continue;
421	            }
422	            int d = c - '0';
423	            if (dbl) {
424	                d *= 2;
425	                if (d > 9) {
426	                    d -= 9;
427	                }
428	            }
429	            sum += d;
430	            dbl = !dbl;
431	        }
432	        return (10 - (sum % 10)) % 10;
433	    }
434	
435	    private static String initial(String name) {
436	        if (name == null || name.isEmpty()) {
437	            return "";
438	        }
439	        return Character.toUpperCase(name.charAt(0)) + ".";
440	    }
